package authz

import (
	"time"

	"github.com/luwa07832/rbac-admin-api/internal/store"
)

// Service runs the time-aware authorization model over one store.
type Service struct {
	store *store.Store
}

// NewService wraps a store.
func NewService(st *store.Store) *Service { return &Service{store: st} }

// timings carries the canonical UTC texts of one write event.
type timings struct {
	occurredAt    string
	effectiveFrom string
}

// bindingRow is a flattened subject/role interval version.
type bindingRow struct {
	seq           int64
	roleID        string
	event         string
	occurredAt    string
	effectiveFrom string
	effectiveTo   string
	id            int64
}

// rolePermRow is a flattened role/permission interval version.
type rolePermRow struct {
	seq           int64
	roleID        string
	permissionID  string
	event         string
	occurredAt    string
	effectiveFrom string
	effectiveTo   string
	id            int64
}

// scopeRow is a flattened scoped authorization interval version. Exactly one
// of roleID and permissionID is set.
type scopeRow struct {
	seq           int64
	roleID        string
	permissionID  string
	scope         scopeRef
	event         string
	occurredAt    string
	effectiveFrom string
	effectiveTo   string
	id            int64
}

// snapshot is the complete read model needed for one decision or history
// query. Interval semantics are evaluated in Go in one place.
type snapshot struct {
	bindings []bindingRow
	rolePerm []rolePermRow
	scopes   []scopeRow

	// roleParents lists static parent roles in stored order.
	roleParents map[string][]string
	// permOperations lists the operations statically covered by permissions.
	permOperations map[string]map[string]bool
}

func (s *Service) loadSnapshot(subject string) (*snapshot, error) {
	snap := &snapshot{
		roleParents:    map[string][]string{},
		permOperations: map[string]map[string]bool{},
	}

	bindingVersions, err := s.store.ListBindingVersions(subject)
	if err != nil {
		return nil, err
	}
	for _, version := range bindingVersions {
		snap.bindings = append(snap.bindings, bindingRow{
			seq:           version.Seq,
			roleID:        version.RoleID,
			event:         version.Event,
			occurredAt:    version.OccurredAt,
			effectiveFrom: version.EffectiveFrom,
			effectiveTo:   version.EffectiveTo,
			id:            version.ID,
		})
	}

	rolePermVersions, err := s.store.ListRolePermissionVersions()
	if err != nil {
		return nil, err
	}
	for _, version := range rolePermVersions {
		snap.rolePerm = append(snap.rolePerm, rolePermRow{
			seq:           version.Seq,
			roleID:        version.RoleID,
			permissionID:  version.PermissionID,
			event:         version.Event,
			occurredAt:    version.OccurredAt,
			effectiveFrom: version.EffectiveFrom,
			effectiveTo:   version.EffectiveTo,
			id:            version.ID,
		})
	}

	scopeVersions, err := s.store.ListScopeVersions(subject)
	if err != nil {
		return nil, err
	}
	for _, version := range scopeVersions {
		parsedScope, ok := parseScope(version.ScopeText)
		if !ok {
			continue
		}
		snap.scopes = append(snap.scopes, scopeRow{
			seq:           version.Seq,
			roleID:        version.RoleID,
			permissionID:  version.PermissionID,
			scope:         parsedScope,
			event:         version.Event,
			occurredAt:    version.OccurredAt,
			effectiveFrom: version.EffectiveFrom,
			effectiveTo:   version.EffectiveTo,
			id:            version.ID,
		})
	}

	roleIDs, err := s.store.ListCatalog(store.CatalogRole)
	if err != nil {
		return nil, err
	}
	for _, roleID := range roleIDs {
		parents, err := s.store.RoleParents(roleID)
		if err != nil {
			return nil, err
		}
		snap.roleParents[roleID] = parents
	}

	permissionIDs, err := s.store.ListCatalog(store.CatalogPermission)
	if err != nil {
		return nil, err
	}
	for _, permissionID := range permissionIDs {
		operations, err := s.store.PermissionOperations(permissionID)
		if err != nil {
			return nil, err
		}
		set := map[string]bool{}
		for _, operation := range operations {
			set[operation] = true
		}
		snap.permOperations[permissionID] = set
	}
	return snap, nil
}

// resolveTimings resolves event and effective times. Both default to now;
// either may be supplied and effectiveFrom need not follow occurredAt.
func (s *Service) resolveTimings(occurredAtText, effectiveFromText string, effectiveField string) (timings, *Failure) {
	now := time.Now().UTC()
	result := timings{occurredAt: FormatTime(now), effectiveFrom: FormatTime(now)}
	if occurredAtText != "" {
		occurred, fail := ParseTime(occurredAtText)
		if fail != nil {
			fail.Field = "occurredAt"
			return timings{}, fail
		}
		result.occurredAt = FormatTime(occurred)
	}
	if effectiveFromText != "" {
		effective, fail := ParseTime(effectiveFromText)
		if fail != nil {
			fail.Field = effectiveField
			return timings{}, fail
		}
		result.effectiveFrom = FormatTime(effective)
	}
	return result, nil
}

// rowActive reports whether the half-open interval [from,to) contains t; an
// empty to marks an open interval.
func rowActive(from, to, at string) bool {
	if from > at {
		return false
	}
	return to == "" || to > at
}
package authz

import (
	"slices"
	"sort"
	"strings"
	"time"

	"github.com/luwa07832/rbac-admin-api/internal/store"
)

// Access sources reported by the effective-access listing.
const (
	SourceRole             = "ROLE"
	SourceDirectPermission = "DIRECT_PERMISSION"
)

// AccessInput is the effective-access query: one subject at one moment.
type AccessInput struct {
	Subject     string
	EffectiveAt string
}

// AccessItem is one effective authorization path in public shape. Role-derived
// items keep the directly bound role alongside the inherited role carrying the
// permission; direct permission grants skip the role layer and leave both role
// fields null.
type AccessItem struct {
	Source     string   `json:"source"`
	BoundRole  *string  `json:"boundRole"`
	Role       *string  `json:"role"`
	Permission string   `json:"permission"`
	Operations []string `json:"operations"`
	Scope      string   `json:"scope"`
}

// Access lists the subject's authorization paths whose three interval layers
// all contain effectiveAt (defaulting to now). The query is read-only and an
// empty result is a normal outcome, never an error. A malformed effectiveAt
// is the one failure that outranks subject validation.
func (s *Service) Access(in AccessInput) ([]AccessItem, *Failure) {
	at := time.Now().UTC()
	if in.EffectiveAt != "" {
		parsed, fail := ParseTime(in.EffectiveAt)
		if fail != nil {
			return nil, fail
		}
		at = parsed
	}
	if !validIdentifier(in.Subject) {
		return nil, invalidRequest("subject", "field subject is not a parseable identifier")
	}
	if exists, err := s.store.Exists(store.CatalogSubject, in.Subject); err != nil || !exists {
		return nil, notFoundOrInternal("subject", err, !exists)
	}
	snap, err := s.loadSnapshot(in.Subject)
	if err != nil {
		return nil, failure(TypeInvalidRequest, "", "could not evaluate access")
	}
	return listAccess(snap, FormatTime(at)), nil
}

// listAccess flattens every authorization path active at the given instant:
// role-derived paths join an active binding, the inherited role's active
// permission grant and an active scope on that same role, while direct
// permission grants stand on their own. Overlapping interval versions of one
// identity collapse into a single item, and the result is ordered by the
// published field sequence.
func listAccess(snap *snapshot, at string) []AccessItem {
	boundRoles := map[string]bool{}
	for _, row := range snap.bindings {
		if rowActive(row.effectiveFrom, row.effectiveTo, at) {
			boundRoles[row.roleID] = true
		}
	}
	reachableCache := map[string]map[string]bool{}
	reachableFrom := func(role string) map[string]bool {
		reachable, ok := reachableCache[role]
		if !ok {
			reachable = reachableRoles(map[string]bool{role: true}, snap.roleParents)
			reachableCache[role] = reachable
		}
		return reachable
	}
	activePairs := map[[2]string]bool{}
	for _, row := range snap.rolePerm {
		if rowActive(row.effectiveFrom, row.effectiveTo, at) {
			activePairs[[2]string{row.roleID, row.permissionID}] = true
		}
	}

	items := []AccessItem{}
	seen := map[string]bool{}
	add := func(source, boundRole, role, permission, scope string) {
		operations := sortedOperations(snap, permission)
		key := strings.Join([]string{source, boundRole, role, permission, scope, strings.Join(operations, "\x00")}, "\x00")
		if seen[key] {
			return
		}
		seen[key] = true
		items = append(items, AccessItem{
			Source:     source,
			BoundRole:  nullable(boundRole),
			Role:       nullable(role),
			Permission: permission,
			Operations: operations,
			Scope:      scope,
		})
	}

	for _, row := range snap.scopes {
		if !rowActive(row.effectiveFrom, row.effectiveTo, at) {
			continue
		}
		if row.permissionID != "" {
			add(SourceDirectPermission, "", "", row.permissionID, row.scope.text)
			continue
		}
		for pair := range activePairs {
			if pair[0] != row.roleID {
				continue
			}
			for boundRole := range boundRoles {
				if reachableFrom(boundRole)[row.roleID] {
					add(SourceRole, boundRole, row.roleID, pair[1], row.scope.text)
				}
			}
		}
	}

	sort.SliceStable(items, func(i, j int) bool { return accessLess(items[i], items[j]) })
	return items
}

// sortedOperations renders the permission's static operation set as a
// deduplicated list ordered by identifier.
func sortedOperations(snap *snapshot, permissionID string) []string {
	operations := []string{}
	for operation := range snap.permOperations[permissionID] {
		operations = append(operations, operation)
	}
	sort.Strings(operations)
	return operations
}

// accessLess orders items by source, boundRole, role, permission, operations
// and scope; absent role fields sort as empty text.
func accessLess(a, b AccessItem) bool {
	if a.Source != b.Source {
		return a.Source < b.Source
	}
	if pointerText(a.BoundRole) != pointerText(b.BoundRole) {
		return pointerText(a.BoundRole) < pointerText(b.BoundRole)
	}
	if pointerText(a.Role) != pointerText(b.Role) {
		return pointerText(a.Role) < pointerText(b.Role)
	}
	if a.Permission != b.Permission {
		return a.Permission < b.Permission
	}
	if cmp := slices.Compare(a.Operations, b.Operations); cmp != 0 {
		return cmp < 0
	}
	return a.Scope < b.Scope
}

func pointerText(value *string) string {
	if value == nil {
		return ""
	}
	return *value
}

