	if len(rolesNow) == 0 && len(rolesPast) > 0 {
		return denied(ReasonNotEffective)
	}

	// Layer 2. A role-derived permission covering the operation is a pair
	// active at the layer time; direct grants live entirely on this layer.
	roleCoversNow := hasCoveringPair(snap, rolesNow, rolePermsNow, operation)
	roleCoversEver := hasCoveringPair(snap, rolesPast, rolePermsAll, operation)

	if !roleCoversNow && (len(directEver) > 0 || roleCoversEver) {
		return denied(ReasonNotEffective)
	}

	// Layer 3. Consider scope rows for paths whose first two layers are
	// active now; an interval that exists but is not active now beats the
	// pattern-mismatch outcome.
	scopeRowsForActivePaths := roleCandidates(snap, rolesNow, rolePermsNow, resource, operation, atText, false)
	if len(directEver) > 0 {
		scopeRowsForActivePaths = append(scopeRowsForActivePaths, directEver...)
	}
	if len(scopeRowsForActivePaths) > 0 {
		return denied(ReasonNotEffective)
	}

	// Structural denials at the first missing layer.
	if len(rolesNow) == 0 {
		return denied(ReasonNoRoleBinding)
	}
	if !roleCoversNow {
		return denied(ReasonNoPermissionBinding)
	}
	return denied(ReasonOutOfScope)
}

func hasCoveringPair(snap *snapshot, roles map[string]bool, rolePerms map[[2]string]bool, operation string) bool {
	for pair := range rolePerms {
		if roles[pair[0]] && permissionCovers(snap, pair[1], operation) {
			return true
		}
	}
	return false
}

func best(candidates []candidate) *Decision {
	sort.SliceStable(candidates, func(i, j int) bool { return candidateLess(candidates[i], candidates[j]) })
	chosen := candidates[0]
	return &Decision{
		Granted: true,
		Match: &Match{
			Role:       chosen.role,
			Permission: chosen.permission,
			Scope:      chosen.scope.text,
		},
	}
}

func denied(reason string) *Decision {
	return &Decision{Granted: false, Reason: reason}
}
package authz

import (
	"regexp"
	"strings"
)

const maxIdentifierLength = 128

var segmentPattern = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._:@-]*$`)

type scopeKind int

const (
	scopeExact scopeKind = iota
	scopePrefix
	scopeAll
)

// scopeRef keeps the original scope text alongside its parsed form so the
// effective scope in a decision is always reported using the stored boundary.
type scopeRef struct {
	text   string
	kind   scopeKind
	prefix string
}

// parseScope accepts the existing scope boundary grammar:
//
//	"*"               matches every resource;
//	"prefix/*"        matches resources equal to "prefix" or under "prefix/";
//	anything else     matches that one resource exactly.
func parseScope(scope string) (scopeRef, bool) {
	if scope == "*" {
		return scopeRef{text: scope, kind: scopeAll}, true
	}
	if strings.HasSuffix(scope, "/*") {
		prefix := strings.TrimSuffix(scope, "/*")
		if prefix == "" || !validIdentifier(prefix) || strings.Contains(prefix, "*") {
			return scopeRef{}, false
		}
		return scopeRef{text: scope, kind: scopePrefix, prefix: prefix}, true
	}
	if strings.Contains(scope, "*") || !validIdentifier(scope) {
		return scopeRef{}, false
	}
	return scopeRef{text: scope, kind: scopeExact, prefix: scope}, true
}

func (s scopeRef) matches(resource string) bool {
	switch s.kind {
	case scopeAll:
		return true
	case scopeExact:
		return s.prefix == resource
	case scopePrefix:
		return strings.HasPrefix(resource, s.prefix+"/")
	}
	return false
}

// compareScope orders scopes from most to least specific: exact match, then
// longest prefix, then the wildcard.
func compareScope(a, b scopeRef) int {
	if a.kind != b.kind {
		if a.kind < b.kind {
			return -1
		}
		return 1
	}
	if a.kind == scopePrefix && len(a.prefix) != len(b.prefix) {
		if len(a.prefix) > len(b.prefix) {
			return -1
		}
		return 1
	}
	return strings.Compare(a.text, b.text)
}

// validIdentifier is the single grammar every identifier must satisfy.
// Hierarchical identifiers may use "/" between non-empty segments.
func validIdentifier(value string) bool {
	if value == "" || len(value) > maxIdentifierLength {
		return false
	}
	if strings.TrimSpace(value) != value {
		return false
	}
	for _, r := range value {
		if r < 0x20 || r == 0x7f {
			return false
		}
	}
	for _, segment := range strings.Split(value, "/") {
		if segment == "" || !segmentPattern.MatchString(segment) {
			return false
		}
	}
	return true
}
package authz

import "github.com/luwa07832/rbac-admin-api/internal/store"

func invalidRequest(field, message string) *Failure {
	return failure(TypeInvalidRequest, field, message)
}

// requireIdentifiers validates the subject/resource/operation triple grammar.
func requireIdentifiers(subject, resource, operation string) *Failure {
	if !validIdentifier(subject) {
		return invalidRequest("subject", "field subject is not a parseable identifier")
	}
	if !validIdentifier(resource) {
		return invalidRequest("resource", "field resource is not a parseable identifier")
	}
	if !validIdentifier(operation) {
		return invalidRequest("operation", "field operation is not a parseable identifier")
	}
	return nil
}

// checkTriple reports the first unknown member of the triple in the published
// order subject, resource, operation.
func (s *Service) checkTriple(subject, resource, operation string) *Failure {
	for _, check := range []struct {
		kind  store.CatalogKind
		id    string
		field string
	}{
		{store.CatalogSubject, subject, "subject"},
		{store.CatalogResource, resource, "resource"},
		{store.CatalogOperation, operation, "operation"},
	} {
		exists, err := s.store.Exists(check.kind, check.id)
		if err != nil {
			return failure(TypeInvalidRequest, check.field, "could not verify "+check.field)
		}
		if !exists {
			return failure(TypeNotFound, check.field, check.field+" does not exist")
		}
	}
	return nil
}
// Package authz implements the time-aware authorization model: versioned
// subject/role bindings, role/permission grants and scoped authorizations,
// historical decisions and change history.
package authz

import (
	"time"

	"github.com/luwa07832/rbac-admin-api/internal/store"
)

// Public error types mirror store.Error so the HTTP layer can render either.
const (
	TypeNotFound       = store.TypeNotFound
	TypeInvalidRequest = store.TypeInvalidRequest
	TypeInvalidTime    = store.TypeInvalidTime
	TypeInvalidRange   = store.TypeInvalidRange
	TypeConflict       = store.TypeConflict
)

// Failure is the structured domain error shared by every abnormal outcome.
type Failure struct {
	Type    string
	Field   string
	Message string
}

func (e *Failure) Error() string { return e.Type + ": " + e.Message }

func failure(typ, field, message string) *Failure {
	return &Failure{Type: typ, Field: field, Message: message}
}

// timeFormat is RFC3339 with nanosecond precision. Every stored and emitted
// timestamp uses this fixed-width UTC layout, so string comparison equals
// chronological comparison.
const timeFormat = "2006-01-02T15:04:05.999999999Z07:00"

// ParseTime accepts an RFC3339 timestamp and returns its canonical UTC text.
// Anything that cannot be parsed (including values outside the supported
// year range) is reported as INVALID_TIME.
func ParseTime(value string) (time.Time, *Failure) {
	parsed, err := time.Parse(time.RFC3339, value)
	if err != nil {
		return time.Time{}, failure(TypeInvalidTime, "effectiveAt", "time must be an RFC3339 timestamp")
	}
	return parsed, nil
}

// FormatTime renders t as canonical RFC3339Nano UTC text.
func FormatTime(t time.Time) string {
	return t.UTC().Format(timeFormat)
}

// intervalActive reports whether the half-open interval [from, to) contains t.
// An empty to marks an open interval.
func intervalActive(from, to string, t time.Time) bool {
	at := FormatTime(t)
	if from > at {
		return false
	}
	return to == "" || to > at
}

